-- Baseline after the metric, installation history, AI and session migrations.
create table action_logs (admin_id bigint, alert_id bigint, created_at datetime(6) not null, id bigint not null auto_increment, action_detail TEXT, primary key (id)) engine=InnoDB;
create table ai_predictions (attempts integer not null, gas_value decimal(18,6) not null, humidity decimal(18,6), temperature decimal(18,6), device_set_history_id bigint, id bigint not null, measured_at datetime(6) not null, next_attempt_at datetime(6) not null, predicted_at datetime(6), queued_at datetime(6) not null, sensor_id bigint not null, sensor_model varchar(8), version bigint not null, zone_id bigint not null, level varchar(32), model_version varchar(64), sample_key varchar(64) not null, device_id varchar(128), error varchar(255), headline varchar(255), result_json LONGTEXT, status enum ('COMPLETE','PENDING','RETRY','RUNNING','SKIPPED') not null, primary key (id)) engine=InnoDB;
create table alerts (created_at datetime(6) not null, device_set_history_id bigint, id bigint not null auto_increment, resolved_at datetime(6), sensor_id bigint, zone_id bigint, level varchar(32), model_version varchar(64), detection_source varchar(16) default 'RULE' not null, message varchar(255), alert_type enum ('FREEZE','LEAK','SMOKING','WINDOW'), status enum ('RESOLVED','UNRESOLVED'), primary key (id)) engine=InnoDB;
create table auth_sessions (created_at datetime(6) not null, expires_at datetime(6) not null, user_id bigint not null, token_hash varchar(64) not null, primary key (token_hash)) engine=InnoDB;
create table cleaning_records (created_at datetime(6) not null, id bigint not null auto_increment, zone_id bigint, memo TEXT, restroom_name varchar(255), type varchar(255), worker varchar(255), primary key (id)) engine=InnoDB;
create table daily_checklists (check_date date not null, is_completed bit not null, completed_at datetime(6), completed_by bigint, id bigint not null auto_increment, zone_id bigint not null, item_key varchar(64) not null, primary key (id)) engine=InnoDB;
create table device_set_history (changed_at datetime(6) not null, device_set_id bigint not null, id bigint not null auto_increment, zone_id bigint not null, mac_address varchar(17) not null, set_code varchar(64) not null, installation_label varchar(100) not null, zone_name varchar(255), primary key (id)) engine=InnoDB;
create table device_sets (created_at datetime(6) not null, id bigint not null auto_increment, updated_at datetime(6) not null, zone_id bigint not null, mac_address varchar(17) not null, set_code varchar(64) not null, installation_label varchar(100) not null, primary key (id)) engine=InnoDB;
create table sensor_data_aggregated (avg_value decimal(20,8) not null, max_value decimal(18,6) not null, min_value decimal(18,6) not null, sum_value decimal(28,6) not null, bucket_start datetime(6) not null, computed_at datetime(6) not null, id bigint not null auto_increment, metric_id bigint not null, sample_count bigint not null, granularity enum ('DAY','HOUR') not null, primary key (id)) engine=InnoDB;
create table sensor_data_raw (measured_value decimal(18,6) not null, device_set_history_id bigint, id bigint not null auto_increment, measured_at datetime(6) not null, metric_id bigint not null, received_at datetime(6) not null, sample_key varchar(64) not null, time_source enum ('DEVICE','LEGACY_SERVER','SERVER') not null, primary key (id)) engine=InnoDB;
create table sensor_metrics (needs_ventilation_threshold decimal(18,6), pleasant_threshold decimal(18,6), created_at datetime(6) not null, id bigint not null auto_increment, sensor_id bigint not null, updated_at datetime(6) not null, unit_code varchar(24) not null, metric_code enum ('CONTACT','GAS','HUMIDITY','TEMPERATURE') not null, primary key (id)) engine=InnoDB;
create table sensors (created_at datetime(6) not null, device_set_id bigint, id bigint not null auto_increment, updated_at datetime(6) not null, zone_id bigint, sensor_model enum ('DHT22','MQ135','MQ7'), sensor_type enum ('GAS','MAG','TEMP_HUMID'), status enum ('ACTIVE','ERROR'), primary key (id)) engine=InnoDB;
create table system_settings (updated_at datetime(6) not null, updated_by bigint, setting_key varchar(64) not null, description varchar(255), setting_value varchar(255) not null, primary key (setting_key)) engine=InnoDB;
create table upstash_devices (last_score float(53) not null, gas_sensor_id bigint not null, temperature_humidity_sensor_id bigint not null, zone_id bigint not null, mac_address varchar(17) not null, primary key (mac_address)) engine=InnoDB;
create table upstash_imported_samples (id bigint not null auto_increment, imported_at datetime(6) not null, measured_at datetime(6) not null, mac_address varchar(17) not null, sample_key varchar(64) not null, ingest_source varchar(16) default 'upstash' not null, payload LONGTEXT not null, primary key (id)) engine=InnoDB;
create table users (created_at datetime(6) not null, id bigint not null auto_increment, updated_at datetime(6) not null, fcm_token varchar(255), password varchar(255) not null, username varchar(255) not null, role enum ('ADMIN','DEVELOPER') not null, primary key (id)) engine=InnoDB;
create table workers (assigned_zone_id bigint, created_at datetime(6) not null, id bigint not null auto_increment, updated_at datetime(6) not null, phone varchar(20) not null, status varchar(20) not null, role varchar(30) not null, name varchar(50) not null, primary key (id)) engine=InnoDB;
create table zone_permissions (created_at datetime(6) not null, id bigint not null auto_increment, user_id bigint, zone_id bigint, primary key (id)) engine=InnoDB;
create table zones (is_active bit, is_our_solution bit, latitude float(53), longitude float(53), needs_ventilation_threshold float(23), pleasant_threshold float(23), created_at datetime(6) not null, id bigint not null auto_increment, updated_at datetime(6) not null, address varchar(255), name varchar(255), zone_type enum ('SMOKING','TOILET'), primary key (id)) engine=InnoDB;
create index ix_ai_work on ai_predictions (status, next_attempt_at, measured_at);
create index ix_ai_sensor_time on ai_predictions (sensor_id, measured_at, id);
create index ix_ai_device_time on ai_predictions (device_id, measured_at, id);
create index ix_auth_session_expiry on auth_sessions (expires_at);
alter table daily_checklists add constraint UKt24j64npmihyilrxlumawel91 unique (zone_id, check_date, item_key);
create index ix_set_history_set_id on device_set_history (device_set_id, id);
alter table device_sets add constraint uq_device_set_code unique (set_code);
alter table device_sets add constraint uq_device_set_mac unique (mac_address);
alter table sensor_data_aggregated add constraint uq_aggregate_bucket unique (metric_id, granularity, bucket_start);
create index ix_raw_metric_time on sensor_data_raw (metric_id, measured_at, id);
create index ix_raw_cleanup on sensor_data_raw (measured_at);
alter table sensor_data_raw add constraint uq_raw_metric_sample unique (metric_id, sample_key);
alter table sensor_metrics add constraint uq_metric_sensor_code unique (sensor_id, metric_code);
alter table sensors add constraint uq_sensor_set_model unique (device_set_id, sensor_model);
create index ix_upstash_device_time on upstash_imported_samples (mac_address, measured_at, id);
alter table upstash_imported_samples add constraint uq_upstash_device_sample unique (mac_address, sample_key);
